<?php

namespace Langsys\SDK\Tests\Format;

use Langsys\SDK\Format\Interpolator;
use Langsys\SDK\Tests\Support\SpyLogger;
use PHPUnit\Framework\TestCase;

/**
 * Tests for placeholder interpolation.
 *
 * Expected values in the ICU / locale-formatting tests are NOT hand-written -
 * they were generated by running the Langsys JS SDK's implementation, so a
 * failure here means the two SDKs would render a shared catalog differently.
 *
 * ICU-dependent tests skip when ext-intl is unavailable, matching the pattern
 * this repo already uses for Redis.
 */
class InterpolatorTest extends TestCase
{
    /**
     * @var Interpolator
     */
    protected $interpolator;

    protected function setUp(): void
    {
        $this->interpolator = new Interpolator();
    }

    /**
     * Skip when ext-intl is unavailable - unless LANGSYS_REQUIRE_INTL is set,
     * in which case fail instead.
     *
     * CI sets that variable so the ICU tests cannot silently skip on a runner
     * that was supposed to have intl. A green suite that skipped every plural
     * assertion is exactly the false confidence this guards against.
     */
    protected function requireIntl()
    {
        if (extension_loaded('intl')) {
            return;
        }

        if (getenv('LANGSYS_REQUIRE_INTL')) {
            $this->fail(
                'ext-intl is not loaded, but LANGSYS_REQUIRE_INTL is set. '
                . 'ICU plural/select behaviour would go unverified.'
            );
        }

        $this->markTestSkipped('ext-intl is not available');
    }

    /**
     * Skip when ext-intl IS present - these cover the degradation path, which
     * only exists when the extension is absent. The CI "Degradation without
     * ext-intl" job is where they actually execute.
     */
    protected function requireMissingIntl()
    {
        if (extension_loaded('intl')) {
            $this->markTestSkipped('This test covers the no-intl degradation path');
        }
    }

    // ---------------------------------------------------------------
    // Simple substitution - runs everywhere, no ext-intl needed
    // ---------------------------------------------------------------

    public function testSubstitutesSinglePlaceholder()
    {
        $this->assertEquals(
            'Hello, Sarah!',
            $this->interpolator->interpolate('Hello, {name}!', ['name' => 'Sarah'])
        );
    }

    public function testSubstitutesMultiplePlaceholders()
    {
        $this->assertEquals(
            'Sarah has 2 items',
            $this->interpolator->interpolate('{name} has {count} items', ['name' => 'Sarah', 'count' => '2'])
        );
    }

    public function testSubstitutesRepeatedPlaceholder()
    {
        $this->assertEquals(
            'Sarah, Sarah!',
            $this->interpolator->interpolate('{name}, {name}!', ['name' => 'Sarah'])
        );
    }

    public function testUnknownKeyLeftVerbatim()
    {
        $this->assertEquals(
            'Hello, Sarah! Bye {other}',
            $this->interpolator->interpolate('Hello, {name}! Bye {other}', ['name' => 'Sarah'])
        );
    }

    public function testNullValueLeftVerbatim()
    {
        $this->assertEquals(
            'Hello, {name}!',
            $this->interpolator->interpolate('Hello, {name}!', ['name' => null])
        );
    }

    public function testWhitespaceInsidePlaceholderTolerated()
    {
        $this->assertEquals(
            'Hi Sarah!',
            $this->interpolator->interpolate('Hi { name }!', ['name' => 'Sarah'])
        );
    }

    public function testEmptyParamsReturnsTextUnchanged()
    {
        $this->assertEquals(
            'Hello, {name}!',
            $this->interpolator->interpolate('Hello, {name}!', [])
        );
    }

    public function testTextWithoutPlaceholdersUnchanged()
    {
        $this->assertEquals(
            'Nothing to do here',
            $this->interpolator->interpolate('Nothing to do here', ['name' => 'Sarah'])
        );
    }

    public function testArrayValueLeftVerbatim()
    {
        $this->assertEquals(
            'Value: {v}',
            $this->interpolator->interpolate('Value: {v}', ['v' => ['a', 'b']])
        );
    }

    public function testObjectWithToStringIsUsed()
    {
        $obj = new class {
            public function __toString()
            {
                return 'stringified';
            }
        };

        $this->assertEquals(
            'Value: stringified',
            $this->interpolator->interpolate('Value: {v}', ['v' => $obj])
        );
    }

    /**
     * An enum renders as Laravel's enum_value() reads it: a backed enum by its
     * value, a plain enum by its name, in a placeholder and as an ICU argument.
     */
    public function testAnEnumParamRendersByItsValueOrName()
    {
        if (PHP_VERSION_ID < 80100) {
            $this->markTestSkipped('Enums need PHP 8.1');
        }

        // Declared at run time, so the file still parses on PHP 7.4.
        if (!class_exists(\Langsys\SDK\Tests\Format\Fixtures\TicketStatus::class, false)) {
            eval('namespace Langsys\SDK\Tests\Format\Fixtures;
                enum TicketStatus: string { case Open = \'open\'; case OnHold = \'on hold\'; }
                enum Priority: int { case High = 3; }
                enum Channel { case Email; }');
        }

        $this->assertSame(
            'Status: on hold, priority 3, via Email',
            $this->interpolator->interpolate('Status: {status}, priority {priority}, via {channel}', [
                'status' => \Langsys\SDK\Tests\Format\Fixtures\TicketStatus::OnHold,
                'priority' => \Langsys\SDK\Tests\Format\Fixtures\Priority::High,
                'channel' => \Langsys\SDK\Tests\Format\Fixtures\Channel::Email,
            ])
        );

        $this->requireIntl();

        $this->assertSame(
            'Abierto por Email',
            $this->interpolator->interpolate('{status, select, open {Abierto} other {Otro}} por {channel}', [
                'status' => \Langsys\SDK\Tests\Format\Fixtures\TicketStatus::Open,
                'channel' => \Langsys\SDK\Tests\Format\Fixtures\Channel::Email,
            ], 'es-es')
        );
    }

    public function testBooleansRenderAsJsStyleTrueFalse()
    {
        // Matches JS String(bool), NOT PHP's native "1" / "".
        $this->assertEquals(
            'a=true b=false',
            $this->interpolator->interpolate('a={a} b={b}', ['a' => true, 'b' => false])
        );
    }

    // ---------------------------------------------------------------
    // Dollar-sign / backreference safety
    //
    // Regression guard: preg_replace would treat $1 / \1 in the REPLACEMENT
    // as backreferences. The JS SDK shipped the equivalent fix in 0.4.1.
    // ---------------------------------------------------------------

    public function testDollarSignInValueNotMangled()
    {
        $this->assertEquals(
            'Price: $5',
            $this->interpolator->interpolate('Price: {price}', ['price' => '$5'])
        );
    }

    public function testBackreferenceLikeValuesNotMangled()
    {
        $this->assertEquals(
            'a=$1 b=\1 c=$& d=$0',
            $this->interpolator->interpolate(
                'a={a} b={b} c={c} d={d}',
                ['a' => '$1', 'b' => '\1', 'c' => '$&', 'd' => '$0']
            )
        );
    }

    public function testDollarSignInSurroundingTextPreserved()
    {
        $this->assertEquals(
            '$5 & $& stays, Sarah',
            $this->interpolator->interpolate('$5 & $& stays, {name}', ['name' => 'Sarah'])
        );
    }

    // ---------------------------------------------------------------
    // Detection helpers
    // ---------------------------------------------------------------

    public function testDetectsIcuSyntax()
    {
        $this->assertTrue($this->interpolator->hasIcuSyntax('{n, plural, one {# item} other {# items}}'));
        $this->assertTrue($this->interpolator->hasIcuSyntax('{g, select, female {She} other {They}}'));
        // Style-less forms must match too.
        $this->assertTrue($this->interpolator->hasIcuSyntax('{v, number}'));
        $this->assertTrue($this->interpolator->hasIcuSyntax('{d, date}'));

        $this->assertFalse($this->interpolator->hasIcuSyntax('Hello, {name}!'));
        $this->assertFalse($this->interpolator->hasIcuSyntax('No placeholders'));
    }

    public function testDetectsPlainPlaceholders()
    {
        $this->assertTrue($this->interpolator->hasPlaceholders('Hello, {name}!'));
        $this->assertFalse($this->interpolator->hasPlaceholders('Hello!'));
    }

    // ---------------------------------------------------------------
    // Missing-intl behaviour: warn loudly, degrade to simple substitution.
    // This is the path that is actually exercised on a host without intl.
    // ---------------------------------------------------------------

    public function testIcuWithoutIntlWarnsAndFallsBackToSimpleSubstitution()
    {
        if (extension_loaded('intl')) {
            $this->markTestSkipped('This test covers the no-intl degradation path');
        }

        $logger = new SpyLogger();
        $interpolator = new Interpolator($logger);

        $result = $interpolator->interpolate(
            'Hello {name}, you have {n, plural, one {# item} other {# items}}',
            ['name' => 'Sarah', 'n' => 2],
            'en-US'
        );

        // Simple placeholders still resolve; the ICU slot is left visible.
        $this->assertStringContainsString('Hello Sarah,', $result);

        $warnings = $logger->messagesAt('warning');
        $this->assertNotEmpty($warnings, 'A missing-intl warning must be logged');
        $this->assertStringContainsString('ext-intl', $warnings[0]);
    }

    public function testMissingIntlWarningEmittedOnlyOncePerInstance()
    {
        if (extension_loaded('intl')) {
            $this->markTestSkipped('This test covers the no-intl degradation path');
        }

        $logger = new SpyLogger();
        $interpolator = new Interpolator($logger);

        $icu = '{n, plural, one {# item} other {# items}}';
        $interpolator->interpolate($icu, ['n' => 1], 'en-US');
        $interpolator->interpolate($icu, ['n' => 2], 'en-US');
        $interpolator->interpolate($icu, ['n' => 5], 'en-US');

        $this->assertCount(1, $logger->messagesAt('warning'));
    }

    /**
     * Without ext-intl an ICU phrase must still read as a SENTENCE.
     *
     * Simple substitution cannot match a construct containing commas and nested
     * braces, so before this fallback existed the raw MessageFormat source was
     * emitted to the page - worse output than an untranslated phrase.
     */
    public function testIcuPluralRendersReadableTextWithoutIntl()
    {
        $this->requireMissingIntl();

        $pattern = '{n, plural, one {# item} other {# items}}';

        $this->assertEquals('1 item', $this->interpolator->interpolate($pattern, ['n' => 1], 'en-US'));
        $this->assertEquals('5 items', $this->interpolator->interpolate($pattern, ['n' => 5], 'en-US'));

        foreach ([1, 5] as $n) {
            $this->assertStringNotContainsString(
                'plural',
                $this->interpolator->interpolate($pattern, ['n' => $n], 'en-US'),
                'Raw MessageFormat source must never reach the page'
            );
        }
    }

    /**
     * Exact `=N` branches are standards-correct and safe without CLDR data.
     */
    public function testIcuExactBranchIsUsedWithoutIntl()
    {
        $this->requireMissingIntl();

        $pattern = '{n, plural, =0 {no items} one {# item} other {# items}}';

        $this->assertEquals('no items', $this->interpolator->interpolate($pattern, ['n' => 0], 'en-US'));
        $this->assertEquals('1 item', $this->interpolator->interpolate($pattern, ['n' => 1], 'en-US'));
    }

    /**
     * A language whose correct category we cannot compute degrades to a single
     * readable form rather than leaking markup.
     */
    public function testRussianPluralDegradesToReadableTextWithoutIntl()
    {
        $this->requireMissingIntl();

        $result = $this->interpolator->interpolate(
            '{n, plural, one {# товар} few {# товара} other {# товаров}}',
            ['n' => 3],
            'ru-RU'
        );

        $this->assertStringNotContainsString('plural', $result);
        $this->assertStringNotContainsString('{', $result);
        $this->assertStringContainsString('3', $result);
    }

    public function testIcuSelectWorksWithoutIntl()
    {
        $this->requireMissingIntl();

        $pattern = '{g, select, male {He} female {She} other {They}} replied';

        $this->assertEquals('She replied', $this->interpolator->interpolate($pattern, ['g' => 'female'], 'en-US'));
        $this->assertEquals('They replied', $this->interpolator->interpolate($pattern, ['g' => 'nonbinary'], 'en-US'));
    }

    public function testNestedPlaceholdersResolveInsideIcuBranchesWithoutIntl()
    {
        $this->requireMissingIntl();

        $this->assertEquals(
            'Hello Sarah, you have 2 msgs',
            $this->interpolator->interpolate(
                'Hello {name}, you have {n, plural, one {# msg} other {# msgs}}',
                ['name' => 'Sarah', 'n' => 2],
                'en-US'
            )
        );
    }

    public function testStyleLessIcuFormsResolveWithoutIntl()
    {
        $this->requireMissingIntl();

        $this->assertEquals(
            '1234 units',
            $this->interpolator->interpolate('{v, number} units', ['v' => 1234], 'en-US')
        );
    }

    /**
     * A missing ICU argument keeps the sentence and shows the gap, on BOTH
     * paths - this used to leave the whole pattern verbatim here while the intl
     * path echoed a bare "{arg}" and destroyed the sentence. Two different
     * broken outputs for one input; now one recovery for both.
     */
    public function testMissingIcuArgumentRecoversIdenticallyWithoutIntl()
    {
        $this->requireMissingIntl();

        $this->assertEquals(
            '{missing} items',
            $this->interpolator->interpolate(
                '{missing, plural, one {# item} other {# items}}',
                ['n' => 2],
                'en-US'
            )
        );

        $this->assertEquals(
            'Bienvenide Sarah',
            $this->interpolator->interpolate(
                '{name_gender, select, male {Bienvenido} female {Bienvenida} other {Bienvenide}} {name}',
                ['name' => 'Sarah'],
                'es-ES'
            )
        );
    }

    /**
     * A parameter value that itself looks like ICU must not be re-scanned.
     * Substituting the value into the branch before recursing made this recurse
     * until memory was exhausted - an uncatchable fatal in a class that promises
     * never to crash.
     */
    public function testIcuValueThatLooksLikeIcuDoesNotRecurseForever()
    {
        $this->requireMissingIntl();

        $result = $this->interpolator->interpolate(
            '{n, plural, other {#}}',
            ['n' => '{n, plural, other {#}}'],
            'en'
        );

        $this->assertNotEquals('', $result);
    }

    /**
     * A nested plural supplies its own '#'; the outer value must not clobber it.
     */
    public function testNestedPluralKeepsItsOwnHashValue()
    {
        $this->requireMissingIntl();

        $this->assertEquals(
            '7 b / 5 a',
            $this->interpolator->interpolate(
                '{a, plural, other {{b, plural, other {# b}} / # a}}',
                ['a' => 5, 'b' => 7],
                'en'
            )
        );
    }

    public function testDeeplyNestedIcuDoesNotExhaustMemory()
    {
        $this->requireMissingIntl();

        $deep = str_repeat('{n, plural, other {', 200) . '#' . str_repeat('}}', 200);

        $this->assertNotEquals('', $this->interpolator->interpolate($deep, ['n' => 1], 'en'));
    }

    /**
     * 1, 1.0 and "1.0" must all take the `one` branch.
     */
    public function testOneBranchSelectedForFloatAndNumericStringWithoutIntl()
    {
        $this->requireMissingIntl();

        $pattern = '{n, plural, one {# item} other {# items}}';

        foreach ([1, 1.0, '1', '1.0'] as $value) {
            $this->assertStringContainsString(
                'item',
                $this->interpolator->interpolate($pattern, ['n' => $value], 'en'),
                'Value ' . var_export($value, true) . ' must take the one branch'
            );
            $this->assertStringNotContainsString(
                'items',
                $this->interpolator->interpolate($pattern, ['n' => $value], 'en')
            );
        }
    }

    public function testNumberFallsBackToPlainStringWithoutIntl()
    {
        if (extension_loaded('intl')) {
            $this->markTestSkipped('This test covers the no-intl degradation path');
        }

        $this->assertEquals(
            'Count: 1234',
            $this->interpolator->interpolate('Count: {n}', ['n' => 1234])
        );
    }

    // ---------------------------------------------------------------
    // ICU plural rules - expected values generated by the JS SDK
    // ---------------------------------------------------------------

    /**
     * 21 -> "one" and 111 -> "many" are the cases that catch naive
     * implementations of the Russian plural rules.
     */
    public function testRussianPluralCategories()
    {
        $this->requireIntl();

        $pattern = '{n, plural, one {# отзыв} few {# отзыва} many {# отзывов} other {# отзыва}}';

        $expected = [
            1 => '1 отзыв',
            2 => '2 отзыва',
            5 => '5 отзывов',
            21 => '21 отзыв',
            22 => '22 отзыва',
            25 => '25 отзывов',
            100 => '100 отзывов',
            111 => '111 отзывов',
        ];

        foreach ($expected as $n => $want) {
            $this->assertEquals(
                $want,
                $this->interpolator->interpolate($pattern, ['n' => $n], 'ru-RU'),
                "Russian plural for n={$n}"
            );
        }
    }

    /**
     * Arabic has six categories. Note the expected output uses Arabic-Indic
     * digits (٣, ١١, ١٠٠) - ar-EG's numbering system, not ASCII.
     */
    public function testArabicPluralCategories()
    {
        $this->requireIntl();

        $pattern = '{n, plural, zero {لا مراجعات} one {مراجعة} two {مراجعتان} few {# مراجعات} many {# مراجعة} other {# مراجعة}}';

        $expected = [
            0 => 'لا مراجعات',
            1 => 'مراجعة',
            2 => 'مراجعتان',
            3 => '٣ مراجعات',
            11 => '١١ مراجعة',
            100 => '١٠٠ مراجعة',
        ];

        foreach ($expected as $n => $want) {
            $this->assertEquals(
                $want,
                $this->interpolator->interpolate($pattern, ['n' => $n], 'ar-EG'),
                "Arabic plural for n={$n}"
            );
        }
    }

    public function testEnglishPluralCategories()
    {
        $this->requireIntl();

        $pattern = '{n, plural, one {# item} other {# items}}';

        $this->assertEquals('0 items', $this->interpolator->interpolate($pattern, ['n' => 0], 'en-US'));
        $this->assertEquals('1 item', $this->interpolator->interpolate($pattern, ['n' => 1], 'en-US'));
        $this->assertEquals('2 items', $this->interpolator->interpolate($pattern, ['n' => 2], 'en-US'));
    }

    public function testIcuSelect()
    {
        $this->requireIntl();

        $pattern = '{g, select, female {She} male {He} other {They}} replied';

        $this->assertEquals('She replied', $this->interpolator->interpolate($pattern, ['g' => 'female'], 'en-US'));
        $this->assertEquals('They replied', $this->interpolator->interpolate($pattern, ['g' => 'nonbinary'], 'en-US'));
    }

    /**
     * A malformed ICU pattern must NOT throw and must NOT blank the string -
     * it falls back to simple substitution, which leaves the ICU-shaped slot
     * untouched because its key contains commas.
     */
    public function testMalformedIcuFallsBackToTemplateUnchanged()
    {
        $this->requireIntl();

        $broken = '{n, plural, one {# item} other {# items}'; // missing closing brace

        $this->assertEquals(
            $broken,
            $this->interpolator->interpolate($broken, ['n' => 2], 'en-US')
        );
    }

    /**
     * ICU-6: a pattern that parses can still fail to format - `{count}` written
     * inside the branches of `{count, plural, ...}` declares one argument with
     * two types, and intl's format() returns false (U_ARGUMENT_TYPE_MISMATCH).
     * The render goes through this SDK's own branch selection with the value
     * filled in: never "", never the raw construct.
     */
    public function testAFormatterFailureRendersThroughTheSdksOwnBranchSelection()
    {
        $this->requireIntl();

        $pattern = 'You have {count, plural, one {{count} car} other {{count} cars}}';

        $this->assertFalse(
            \MessageFormatter::create('en', $pattern)->format(['count' => 3]),
            'the vector must make intl fail at format time'
        );

        $this->assertSame('You have 3 cars', $this->interpolator->interpolate($pattern, ['count' => 3], 'en'));
        $this->assertSame('You have 1 car', $this->interpolator->interpolate($pattern, ['count' => 1], 'en'));
    }

    /**
     * ICU-6's CLDR clause: where intl can compute the value's category, the
     * fallback uses it - Polish 3 is `few`, which one-iff-1 would render as
     * `other`.
     */
    public function testAFormatterFailurePicksTheCldrCategory()
    {
        $this->requireIntl();

        $pattern = '{n, plural, one {# kot} few {# koty} many {# kotów} other {# kota}} ({n})';

        $this->assertFalse(\MessageFormatter::create('pl', $pattern)->format(['n' => 3]));

        $this->assertSame('3 koty (3)', $this->interpolator->interpolate($pattern, ['n' => 3], 'pl'));
        $this->assertSame('5 kotów (5)', $this->interpolator->interpolate($pattern, ['n' => 5], 'pl'));
        $this->assertSame('1 kot (1)', $this->interpolator->interpolate($pattern, ['n' => 1], 'pl'));

        // An ordinal takes the ordinal rules, not the cardinal ones: English 2
        // is `two` (2nd) and 11 is `other` (11th).
        $ordinal = '{n, selectordinal, one {#st} two {#nd} few {#rd} other {#th}} ({n})';
        $this->assertFalse(\MessageFormatter::create('en', $ordinal)->format(['n' => 2]));

        $this->assertSame('2nd (2)', $this->interpolator->interpolate($ordinal, ['n' => 2], 'en'));
        $this->assertSame('11th (11)', $this->interpolator->interpolate($ordinal, ['n' => 11], 'en'));
        $this->assertSame('22nd (22)', $this->interpolator->interpolate($ordinal, ['n' => 22], 'en'));
    }

    /**
     * ICU-6's warning fires with debug logging off - a formatter failure is a
     * defect in the phrase, not the normal event ICU-4 notes at debug - names
     * the phrase, the locale and intl's error, and fires once per template and
     * locale.
     */
    public function testAFormatterFailureWarnsWithDebugOffOncePerTemplateAndLocale()
    {
        $this->requireIntl();

        $path = tempnam(sys_get_temp_dir(), 'langsys-icu6-');
        $interpolator = new Interpolator(new \Langsys\SDK\Log\Logger($path, 'warning'));

        $pattern = 'You have {count, plural, one {{count} car} other {{count} cars}}';

        $interpolator->interpolate($pattern, ['count' => 3], 'en');
        $interpolator->interpolate($pattern, ['count' => 5], 'en');
        $interpolator->interpolate($pattern, ['count' => 3], 'de');

        $lines = array_values(array_filter(explode("\n", (string) file_get_contents($path))));
        @unlink($path);

        $warnings = array_values(array_filter($lines, function ($line) {
            return strpos($line, 'ICU formatting failed') !== false;
        }));

        $this->assertCount(2, $warnings, 'one warning per (template, locale): en once, de once');
        foreach ($warnings as $warning) {
            $this->assertStringContainsString('You have {count, plural', $warning);
            $this->assertStringContainsString('U_ARGUMENT_TYPE_MISMATCH', $warning);
        }
        $this->assertStringContainsString('"locale":"en"', $warnings[0]);
        $this->assertStringContainsString('"locale":"de"', $warnings[1]);
    }

    /**
     * The interpolation reference fixtures, asserted against by other Langsys
     * SDKs so a shared catalog renders the same sentence everywhere.
     *
     * This file exists because three of the four cross-SDK defects found so far
     * had a standing check afterwards and the fourth did not: markup tokens and
     * content-block ids are pinned by the other two fixture files, but nothing
     * pinned what a phrase RENDERS AS. Both SDKs shipped different broken output
     * for a missing ICU argument, and neither suite noticed, because every test
     * on both sides supplied complete params.
     *
     * ICU cases skip without ext-intl - the recovery path is shared, but real
     * plural-rule selection is not.
     */
    public function testInterpolationMatchesTheReferenceFixtures()
    {
        $path = dirname(__DIR__) . '/fixtures/interpolation-reference.json';

        $this->assertFileExists($path);

        $cases = json_decode(file_get_contents($path), true);

        $this->assertNotEmpty($cases);

        // Every row once supplied a params object, which is how three SDKs shipped a
        // no-params short-circuit that returned the raw pattern with every fixture
        // run green. Both shapes must stay in the file.
        $this->assertNotEmpty(array_filter($cases, function ($case) {
            return !array_key_exists('params', $case);
        }), 'the fixture must keep a row with no params at all');
        $this->assertNotEmpty(array_filter($cases, function ($case) {
            return array_key_exists('params', $case) && $case['params'] === [];
        }), 'the fixture must keep a row with an empty params map');

        foreach ($cases as $case) {
            // requires_intl is MEASURED at generation time by running each case
            // with and without the extension, not guessed from the template -
            // a plain {id} placeholder needs intl for locale number formatting
            // while an ICU recovery case does not.
            if (!empty($case['requires_intl']) && !extension_loaded('intl')) {
                continue;
            }

            $this->assertSame(
                $case['expected'],
                // A row without params maps to the default []: passing a locale
                // positionally means this API cannot omit the argument itself.
                // ClientInterpolationTest drives the genuinely omitted form.
                $this->interpolator->interpolate($case['template'], array_key_exists('params', $case) ? $case['params'] : [], $case['locale']),
                $case['description'] . ' — ' . $case['template']
            );
        }
    }

    // ---------------------------------------------------------------
    // Missing ICU arguments
    //
    // The backend promotes a plain {name} into {name_gender, select, ...} for
    // gendered target locales, so the argument does not exist in the source
    // phrase the developer wrote and nothing tells them the target grew one.
    // This is therefore reachable without any caller error.
    //
    // MessageFormatter does NOT throw or return false for a well-formed pattern
    // with a missing argument - it echoes a bare "{argName}" - so the
    // malformed-ICU fallback never fired and the sentence was destroyed.
    // ---------------------------------------------------------------

    public function testMissingSelectArgumentRendersTheNeutralBranch()
    {
        $pattern = '{name_gender, select, male {Bienvenido} female {Bienvenida} other {Bienvenide}} {name}';

        // A select always provides `other`, so the sentence is recoverable and
        // the result is CORRECT rather than merely readable.
        $this->assertEquals(
            'Bienvenide Sarah',
            $this->interpolator->interpolate($pattern, ['name' => 'Sarah'], 'es-ES')
        );

        $this->assertStringNotContainsString('{name_gender}', $this->interpolator->interpolate($pattern, ['name' => 'Sarah'], 'es-ES'));
    }

    public function testMissingSelectArgumentDoesNotAffectTheCompleteCase()
    {
        $pattern = '{name_gender, select, male {Bienvenido} female {Bienvenida} other {Bienvenide}} {name}';

        $this->assertEquals(
            'Bienvenida Sarah',
            $this->interpolator->interpolate($pattern, ['name' => 'Sarah', 'name_gender' => 'female'], 'es-ES')
        );
    }

    /**
     * A plural has no neutral branch to infer, so the count stays visible while
     * the sentence around it survives - strictly better than both destroying the
     * sentence and dumping the raw pattern.
     */
    public function testMissingPluralArgumentKeepsTheSentenceAndShowsTheGap()
    {
        $result = $this->interpolator->interpolate(
            '{count, plural, one {# item} other {# items}}',
            ['name' => 'Sarah'],
            'es-ES'
        );

        $this->assertEquals('{count} items', $result);
        $this->assertStringNotContainsString('plural', $result, 'The pattern must never be dumped to the page');
    }

    /**
     * The recovery must not depend on ext-intl: it routes through the same
     * branch-selecting renderer either way, so a host missing the extension
     * gets the same output rather than a third behaviour.
     */
    public function testMissingArgumentBehavesIdenticallyWithAndWithoutIntl()
    {
        // Documents the contract; the no-intl half is exercised by the CI job
        // that runs the suite without the extension.
        $this->assertEquals(
            'Bienvenide Sarah',
            $this->interpolator->interpolate(
                '{name_gender, select, male {Bienvenido} female {Bienvenida} other {Bienvenide}} {name}',
                ['name' => 'Sarah'],
                'es-ES'
            )
        );
    }

    public function testNullArgumentIsTreatedAsMissing()
    {
        $this->assertEquals(
            'Bienvenide Sarah',
            $this->interpolator->interpolate(
                '{name_gender, select, male {Bienvenido} female {Bienvenida} other {Bienvenide}} {name}',
                ['name' => 'Sarah', 'name_gender' => null],
                'es-ES'
            )
        );
    }

    // ---------------------------------------------------------------
    // Locale-aware number formatting
    // ---------------------------------------------------------------

    public function testNumberFormattingPerLocale()
    {
        $this->requireIntl();

        // ru-RU groups with U+00A0 NO-BREAK SPACE, not an ASCII space.
        $expected = [
            'de-DE' => '1.234,5',
            'ru-RU' => "1\xc2\xa0234,5",
            'en-US' => '1,234.5',
            'ar-EG' => '١٬٢٣٤٫٥',
        ];

        foreach ($expected as $locale => $want) {
            $this->assertEquals(
                $want,
                $this->interpolator->interpolate('{v}', ['v' => 1234.5], $locale),
                "Number formatting for {$locale}"
            );
        }
    }

    /**
     * The ICU number path and the simple path must agree byte-for-byte,
     * otherwise the same value renders differently depending on which
     * syntax an author happened to use.
     */
    public function testIcuNumberMatchesSimplePathExactly()
    {
        $this->requireIntl();

        foreach (['de-DE', 'ru-RU', 'en-US', 'ar-EG'] as $locale) {
            $this->assertEquals(
                $this->interpolator->interpolate('{v}', ['v' => 1234.5], $locale),
                $this->interpolator->interpolate('{v, number}', ['v' => 1234.5], $locale),
                "ICU and simple number paths must agree for {$locale}"
            );
        }
    }

    /**
     * Documented escape hatch: pass a value as a string to opt out of
     * grouping separators - for IDs, codes and version numbers.
     */
    public function testStringValueOptsOutOfNumberFormatting()
    {
        $this->requireIntl();

        $this->assertEquals(
            'Order 1234567',
            $this->interpolator->interpolate('Order {id}', ['id' => '1234567'], 'de-DE')
        );

        $this->assertEquals(
            'Order 1.234.567',
            $this->interpolator->interpolate('Order {id}', ['id' => 1234567], 'de-DE')
        );
    }

    // ---------------------------------------------------------------
    // Dates
    //
    // IntlDateFormatter uses the runtime's default timezone, so a fixture
    // pinned to a bare date is NOT portable across CI boxes (the JS SDK hit
    // exactly this: Date.UTC(2026,6,8) rendered "Jul 7, 2026" at UTC-6).
    // These tests pin the timezone explicitly and assert on FORMAT.
    // ---------------------------------------------------------------

    public function testDateFormattingIsLocaleAware()
    {
        $this->requireIntl();

        $originalTz = date_default_timezone_get();
        date_default_timezone_set('UTC');

        try {
            // Midday UTC: no plausible offset moves this across a date boundary.
            $date = new \DateTimeImmutable('2026-07-08 12:00:00', new \DateTimeZone('UTC'));

            $enUs = $this->interpolator->interpolate('{d}', ['d' => $date], 'en-US');
            $deDe = $this->interpolator->interpolate('{d}', ['d' => $date], 'de-DE');

            // Assert on shape and the correct day, not on an exact fixture string
            // (ICU data formats vary between library versions).
            $this->assertStringContainsString('2026', $enUs);
            $this->assertStringContainsString('8', $enUs);
            $this->assertNotEquals($enUs, $deDe, 'Locales must format dates differently');
            $this->assertStringContainsString('2026', $deDe);
        } finally {
            date_default_timezone_set($originalTz);
        }
    }

    public function testDateFallsBackToIsoWithoutIntl()
    {
        if (extension_loaded('intl')) {
            $this->markTestSkipped('This test covers the no-intl degradation path');
        }

        $date = new \DateTimeImmutable('2026-07-08 12:00:00', new \DateTimeZone('UTC'));

        $this->assertEquals(
            '2026-07-08',
            $this->interpolator->interpolate('{d}', ['d' => $date])
        );
    }

    /**
     * MessageFormatter signals a bad pattern with false by default and with an
     * IntlException when intl.use_exceptions=1, which '@' does not suppress.
     * Behaviour already present on this line; pinned under BOTH ini states,
     * because testing only one would miss the bug entirely.
     *
     * @dataProvider useExceptionsProvider
     */
    public function testMalformedIcuNeverThrows($useExceptions)
    {
        if (!class_exists('MessageFormatter')) {
            $this->markTestSkipped('ext-intl is not available.');
        }

        $previous = ini_get('intl.use_exceptions');
        ini_set('intl.use_exceptions', $useExceptions);

        try {
            $out = (new Interpolator())->interpolate(
                '{n, plural, one {# item} other {# items}',
                ['n' => 2],
                'en-us'
            );
            $this->assertIsString($out);
        } finally {
            ini_set('intl.use_exceptions', $previous === false ? '0' : $previous);
        }
    }

    public function useExceptionsProvider()
    {
        return [
            'intl.use_exceptions=0' => ['0'],
            'intl.use_exceptions=1' => ['1'],
        ];
    }

    // =========================================================================
    // ICU-4 — recovery must be observable
    // =========================================================================

    /**
     * A recovered argument never appears in the source phrase, so there is
     * nothing to grep for and no failing behaviour to notice: the page renders,
     * reads plausibly, and is subtly wrong. Asserting the notice fires AND names
     * the argument — a test that only checks the rendered string passes whether
     * or not anyone can ever diagnose it.
     */
    public function testRecoveryEmitsADebugNoticeNamingEveryDefaultedArgument()
    {
        $this->requireIntl();

        $logger = new RecordingLogger();
        $interpolator = new Interpolator($logger);

        $interpolator->interpolate(
            '{gender, select, male {M} other {O}} and {mood, select, glad {G} other {N}}',
            ['unrelated' => 1],
            'pl'
        );

        $this->assertCount(1, $logger->records, 'exactly one notice per recovering render');

        list($level, $message, $context) = $logger->records[0];

        $this->assertSame('debug', $level);
        $this->assertSame(['gender', 'mood'], $context['defaulted_arguments'], 'every defaulted argument is named');
        $this->assertSame('pl', $context['locale']);
        $this->assertStringContainsString('params', $message, 'the notice states the fix');
        $this->assertStringContainsString('NORMAL', $message, 'and that a source phrase lacking the argument is expected');
    }

    /**
     * Deduped per locale + template, so a recovering phrase rendered on every
     * request produces one line rather than a flood — and a second locale is a
     * genuinely different rendering, so it notes again.
     */
    public function testRecoveryNoticeIsDedupedPerLocaleAndTemplate()
    {
        $this->requireIntl();

        $logger = new RecordingLogger();
        $interpolator = new Interpolator($logger);
        $template = '{gender, select, male {M} other {O}}';

        $interpolator->interpolate($template, ['x' => 1], 'pl');
        $interpolator->interpolate($template, ['x' => 1], 'pl');
        $interpolator->interpolate($template, ['x' => 1], 'ru');

        $this->assertCount(2, $logger->records);
        $this->assertSame('pl', $logger->records[0][2]['locale']);
        $this->assertSame('ru', $logger->records[1][2]['locale']);
    }

    /**
     * The notice must fire for NON-select argument types too.
     *
     * Coverage, not behaviour: the notice is emitted from the recovery decision,
     * which is argument-type-agnostic — it reads the names `missingIcuArguments()`
     * found and never inspects their type. So this passes today and is expected
     * to. It exists because the other three notice tests all recover `select`
     * arguments, and a suite that only ever recovers one argument type cannot
     * distinguish "the notice fires on recovery" from "the notice fires on
     * select" — a later change making the notice type-specific would leave every
     * existing assertion green.
     */
    public function testRecoveryNoticeFiresForPluralAndNumberArgumentsToo()
    {
        $this->requireIntl();

        $logger = new RecordingLogger();

        (new Interpolator($logger))->interpolate(
            '{n, plural, one {# item} other {# items}} and {m, number} more',
            ['unrelated' => 1],
            'pl'
        );

        $this->assertCount(1, $logger->records);

        list($level, , $context) = $logger->records[0];

        $this->assertSame('debug', $level);
        $this->assertSame(['n', 'm'], $context['defaulted_arguments'], 'both non-select types are named');
        $this->assertSame('pl', $context['locale']);
    }

    public function testNoNoticeWhenNothingWasDefaulted()
    {
        $this->requireIntl();

        $logger = new RecordingLogger();

        (new Interpolator($logger))->interpolate(
            '{gender, select, male {M} other {O}}',
            ['gender' => 'male'],
            'pl'
        );

        $this->assertSame([], $logger->records);
    }

    // =========================================================================
    // Supplied arguments keep CLDR selection while others recover
    // =========================================================================

    /**
     * The divergence this closes: one missing argument used to route the WHOLE
     * string to the simplified renderer, whose branch selection knows only `=N`,
     * one-iff-1 and `other`. So a SUPPLIED plural at n=3 rendered `other` in
     * Polish, Russian and Arabic where CLDR requires `few` — grammatically wrong
     * output in every language that marks the distinction, caused by an
     * unrelated argument being absent.
     *
     * @dataProvider cldrFewProvider
     */
    public function testSuppliedPluralKeepsCldrSelectionWhileAnotherArgumentRecovers($locale, $expected)
    {
        $this->requireIntl();

        $out = (new Interpolator())->interpolate(
            '{gender, select, male {M} female {F} other {O}} — {n, plural, one {# item} few {# items-few} many {# items-many} other {# items-other}}',
            ['n' => 3],
            $locale
        );

        // The count is written in the locale's own digits, which differ
        // between ICU versions: Arabic's is 3 on ICU 76.1 and 78.2, ٣ on 74.2.
        $digits = (new \NumberFormatter($locale, \NumberFormatter::DECIMAL))->format(3);
        $this->assertSame(str_replace('3', $digits, $expected), $out);
    }

    public function cldrFewProvider()
    {
        return [
            'pl n=3 is few'      => ['pl', 'O — 3 items-few'],
            'ru n=3 is few'      => ['ru', 'O — 3 items-few'],
            'ar n=3 is few'      => ['ar', 'O — 3 items-few'],
            // English has no `few` category, so `other` is correct here - the
            // control that proves the assertion tracks CLDR rather than a string.
            'en-us n=3 is other' => ['en-us', 'O — 3 items-other'],
        ];
    }

    /**
     * Recovery descends: a missing argument nested inside a SUPPLIED select
     * recovers, while the select itself stays on the CLDR path.
     *
     * The first version of this test supplied BOTH arguments, so nothing was
     * missing, nothing recovered, and it asserted the ordinary intl path while
     * claiming to prove descent — it would have passed against an SDK with no
     * descent at all. `n` is withheld here so the nested node must actually be
     * rewritten.
     *
     * CHARACTERISATION, not a regression pin: this case produces the same string
     * under the previous whole-string renderer, because a MISSING argument has no
     * CLDR category to lose — both implementations land on `other`. The vectors
     * that discriminate are the ones with a SUPPLIED plural alongside
     * (`cldrFewProvider`). Recorded so nobody reads a green here as evidence the
     * node-by-node rewrite is working.
     */
    public function testRecoveryDescendsIntoASuppliedNode()
    {
        $this->requireIntl();

        $template = '{g, select, female {F: {n, plural, one {# item} few {# few} other {# other}}} other {O}}';

        // g supplied and selected by CLDR; n missing and recovered in place.
        $this->assertSame(
            'F: {n} other',
            (new Interpolator())->interpolate($template, ['g' => 'female'], 'pl')
        );

        // Control: with n supplied, the same nested node takes the CLDR branch,
        // so the assertion above is about recovery rather than about the string.
        $this->assertSame(
            'F: 3 few',
            (new Interpolator())->interpolate($template, ['g' => 'female', 'n' => 3], 'pl')
        );
    }

    /**
     * The commonest call shape. A catalog value can contain an ICU construct the
     * caller knows nothing about — the backend promotes a plain {name} into a
     * gendered select for locales that need one — so "no params" is precisely
     * the case that needs recovery. This used to return the raw MessageFormat
     * source to the page.
     */
    public function testIcuRecoversWhenTheCallerSuppliesNoParamsAtAll()
    {
        $out = (new Interpolator())->interpolate(
            '{count, plural, one {# item} other {# items}}',
            [],
            'en-us'
        );

        $this->assertSame('{count} items', $out);
        $this->assertStringNotContainsString('plural', $out, 'raw ICU source must never reach the page');
    }

    /**
     * The recovered `{argName}` literal must survive the formatter call — for
     * TYPED arguments as well as branch-typed ones, and whether the argument is
     * absent or present-and-null.
     *
     * Two failure modes, both surfaced by mutating the recovery on the JS leg and
     * both invisible to the branch-typed vectors above:
     *
     *   - a null NUMBER coerces to `'0 due'` rather than erasing to `' due'`.
     *     That is worse than the empty string, because `0` reads as data: an
     *     invoice showing "0 due" is a plausible sentence stating something false,
     *     where " due" at least looks broken.
     *   - the same mutation breaks ABSENT-argument recovery outright, emitting raw
     *     ICU source. So the absent cases sit beside the null ones deliberately —
     *     a suite with only null vectors passes while absent recovery is gone.
     *
     * @dataProvider recoveredLiteralProvider
     */
    public function testRecoveredLiteralSurvivesTheFormatterCall($template, $params, $expected)
    {
        $this->assertSame($expected, (new Interpolator())->interpolate($template, $params, 'en-us'));
    }

    public function recoveredLiteralProvider()
    {
        return [
            // A null typed argument must not coerce. '0 due' would be the
            // dangerous outcome; ' due' the merely broken one.
            'null number'            => ['{amt, number} due', ['amt' => null], '{amt} due'],
            'absent number'          => ['{amt, number} due', [], '{amt} due'],
            'absent number, params'  => ['{amt, number} due', ['other' => 1], '{amt} due'],
            'null date'              => ['{d, date} shipped', ['d' => null], '{d} shipped'],
            'absent date'            => ['{d, date} shipped', ['other' => 1], '{d} shipped'],
            'null plural'            => ['{n, plural, one {# item} other {# items}}', ['n' => null], '{n} items'],
            'absent plural'          => ['{n, plural, one {# item} other {# items}}', [], '{n} items'],
            // {count} inside its own plural fails to format on ICU 76.1 (ICU-6).
            'after a formatter failure' => ['{count, plural, one {{count} car} other {{count} cars}}, {amt, number} due', ['count' => 3], '3 cars, {amt} due'],

            // Controls: a supplied argument still formats through CLDR, so the
            // assertions above are about recovery rather than about the type
            // never formatting at all.
            // Without intl a number prints as given.
            'supplied number'        => ['{amt, number} due', ['amt' => 1234.5], extension_loaded('intl') ? '1,234.5 due' : '1234.5 due'],
            'supplied plural'        => ['{n, plural, one {# item} other {# items}}', ['n' => 1], '1 item'],
        ];
    }

    /**
     * A recovered branch holds its values as written, as the same branch does
     * with its argument supplied: a value is never read as ICU, so it never
     * fills in another param, unescapes a quote or takes a plural's count.
     *
     * @dataProvider recoveredValueProvider
     */
    public function testARecoveredBranchKeepsItsValuesAsWritten($template, array $params, $expected)
    {
        $interpolator = new Interpolator();

        $this->assertSame($expected, $interpolator->interpolate($template, $params, 'es-ES'));
        $this->assertSame($expected, $interpolator->interpolate($template, $params + ['g' => 'other'], 'es-ES'), 'control: the argument supplied');
    }

    public function recoveredValueProvider()
    {
        $welcome = '{g, select, female {Bienvenida, {name}} other {Bienvenide, {name}}}';

        return [
            'another param named'   => [$welcome, ['name' => '{order}', 'order' => 'SECRET'], 'Bienvenide, {order}'],
            'a doubled quote'       => [$welcome, ['name' => "It''s me"], "Bienvenide, It''s me"],
            'a quoted brace'        => [$welcome, ['name' => "a'{b}'c"], "Bienvenide, a'{b}'c"],
            'ICU syntax'            => [$welcome, ['name' => '{count, plural, other {#}}', 'count' => 7], 'Bienvenide, {count, plural, other {#}}'],
            'a # inside a plural'   => ['{n, plural, other {# {g, select, other {fans de {team}}}}}', ['n' => 3, 'team' => '#1 Club'], '3 fans de #1 Club'],
        ];
    }

    /**
     * A recovering phrase that does not parse is named in the warning as
     * written, never as the pattern its recovery handed intl.
     */
    public function testARecoveringPhraseThatDoesNotParseIsNamedAsWritten()
    {
        $logger = new RecordingLogger();
        $template = '{g, select, other {Hola}} {broken';

        (new Interpolator($logger))->interpolate($template, [], 'es-ES');

        $warnings = array_values(array_filter($logger->records, function ($record) {
            return $record[0] === 'warning';
        }));
        $this->assertNotEmpty($warnings);
        $this->assertSame($template, $warnings[0][2]['phrase']);
    }

    /**
     * `#` is a plural's count. In a select's branch it is text, as ICU and the
     * JS formatter both read it, the select nested in a plural or not:
     * recovered, rendered after a formatter failure, or formatted.
     *
     * @dataProvider hashInASelectProvider
     */
    public function testAHashInASelectBranchIsText($template, array $params, $expected)
    {
        $this->assertSame($expected, (new Interpolator())->interpolate($template, $params, 'es-ES'));
    }

    public function hashInASelectProvider()
    {
        $rank = '{g, select, female {Ella es la #1} other {Es el #1}}';
        $friends = '{n, plural, one {{g, select, female {# amiga} other {# amigo}}} other {{g, select, female {# amigas} other {# amigos}}}}';
        // {count} inside its own plural fails to format on ICU 76.1 (ICU-6).
        $failing = 'Tienes {count, plural, one {{count} coche} other {{count} coches}}. ';

        return [
            'recovered'                    => [$rank, [], 'Es el #1'],
            'recovered inside a plural'    => [$friends, ['n' => 3], '# amigos'],
            'after a formatter failure'    => [$failing . $rank, ['count' => 3, 'g' => 'female'], 'Tienes 3 coches. Ella es la #1'],
            'control: formatted'           => [$rank, ['g' => 'female'], 'Ella es la #1'],
            'control: formatted in plural' => [$friends, ['n' => 3, 'g' => 'female'], '# amigas'],
        ];
    }

    /**
     * A date in a plain `{d}` renders as a date in a phrase with ICU in it, as
     * it does in one without: recovered or formatted, never as a timestamp.
     *
     * @dataProvider dateInAnIcuPhraseProvider
     */
    public function testADateInAPlainPlaceholderOfAnIcuPhraseRendersAsADate($template, array $params, $expected)
    {
        $interpolator = new Interpolator();
        $date = new \DateTimeImmutable('2026-03-05 10:00:00', new \DateTimeZone('UTC'));

        $this->assertSame(
            sprintf($expected, $interpolator->interpolate('{d}', ['d' => $date], 'es')),
            $interpolator->interpolate($template, $params + ['d' => $date], 'es')
        );
    }

    public function dateInAnIcuPhraseProvider()
    {
        return [
            'formatted'       => ['{n, plural, one {# factura vence} other {# facturas vencen}} el {d}', ['n' => 3], '3 facturas vencen el %s'],
            'recovered'       => ['{g, select, other {Vence}} el {d}', [], 'Vence el %s'],
            'inside a branch' => ['{n, plural, one {# factura vence el {d}} other {# facturas vencen el {d}}}', ['n' => 3], '3 facturas vencen el %s'],
        ];
    }

    /**
     * A number in a plain `{n}` is locale-formatted in a phrase that MessageFormatter
     * formats, as it is outside ICU: PHP's formatter prints an untyped number as
     * `1234.5`. A typed argument stays a number, so a plural still selects and
     * `#` still formats.
     *
     * @dataProvider numberInAnIcuPhraseProvider
     */
    public function testANumberInAPlainPlaceholderOfAnIcuPhraseIsLocaleFormatted($template, array $params, $expected)
    {
        $this->requireIntl();

        $interpolator = new Interpolator();

        // Positive control: the same value outside ICU is formatted.
        $this->assertSame('Summe 1.234,5', $interpolator->interpolate('Summe {n}', ['n' => 1234.5], 'de-DE'));
        $this->assertSame($expected, $interpolator->interpolate($template, $params, 'de-DE'));
    }

    public function numberInAnIcuPhraseProvider()
    {
        return [
            'float in a select branch'  => ['{g, select, female {Ana zahlte {n}} other {Er zahlte {n}}}', ['g' => 'female', 'n' => 1234.5], 'Ana zahlte 1.234,5'],
            'int beside a plural'       => ['{c, plural, one {# Artikel} other {# Artikel}} für {n}', ['c' => 3, 'n' => 1234567], '3 Artikel für 1.234.567'],
            'plural count with #'       => ['{c, plural, one {# Artikel} other {# Artikel}}', ['c' => 1234], '1.234 Artikel'],
            'plural still selects one'  => ['{c, plural, one {ein Artikel} other {# Artikel}}', ['c' => 1], 'ein Artikel'],
            'a string stays as written' => ['{g, select, other {Nr. {n}}}', ['g' => 'x', 'n' => '1234.5'], 'Nr. 1234.5'],
            // ICU reads a right-to-left mark or line separator as whitespace,
            // so the count is still typed and selects its branch.
            'RLM after a plural name'   => ["{c\u{200F}, plural, one {ein Artikel} other {# Artikel}}", ['c' => 1234], '1.234 Artikel'],
            'LS before a plural name'   => ["{\u{2028}c, plural, one {ein Artikel} other {# Artikel}}", ['c' => 1234], '1.234 Artikel'],
        ];
    }

    // =========================================================================
    // TOK-5 — %name% is an accepted spelling of {name}
    // =========================================================================

    /**
     * Before this, `%name%` reached the reader verbatim: a placeholder rendered
     * as literal text on the page. The two spellings exist because different
     * hosts template differently, and the catalog is shared across all of them.
     *
     * @dataProvider percentPlaceholderProvider
     */
    public function testPercentPlaceholdersAreAccepted($text, array $params, $expected, $why)
    {
        $this->assertSame($expected, $this->interpolator->interpolate($text, $params, 'en-us'), $why);
    }

    public function percentPlaceholderProvider()
    {
        return [
            'percent form substitutes' => [
                'Hello, %name%!', ['name' => 'Sarah'], 'Hello, Sarah!',
                'the escape form must behave exactly like the brace form',
            ],
            'brace form still substitutes' => [
                'Hello, {name}!', ['name' => 'Sarah'], 'Hello, Sarah!',
                'positive control - adding one spelling must not cost the other',
            ],
            'both forms in one string' => [
                'Hi {a} and %b%', ['a' => 'X', 'b' => 'Y'], 'Hi X and Y',
                'a phrase may legitimately carry both',
            ],
            'ICU is unaffected' => [
                '{n, plural, one {# item} other {# items}}', ['n' => 3], '3 items',
                'the normalisation runs before ICU and must not disturb it',
            ],

            // The reason the pattern is narrow and gated on supplied keys.
            'percentages are not placeholders' => [
                'Save 20% on 5% APR', ['name' => 'Sarah'], 'Save 20% on 5% APR',
                'ordinary prose containing a %...% span must not be eaten',
            ],
            'percentages with no params at all' => [
                'Save 20% on 5% APR', [], 'Save 20% on 5% APR',
                'and the same with nothing supplied',
            ],
            'unsupplied key is left verbatim' => [
                '%unknown% stays', ['name' => 'Sarah'], '%unknown% stays',
                'an unmatched key must be returned as written, not turned into a visible {unknown}',
            ],
            'a CSS-ish value survives' => [
                'width: 100%; height: 50%', ['name' => 'Sarah'], 'width: 100%; height: 50%',
                'a rewrite that is not gated on supplied keys would mangle this',
            ],
        ];
    }

    /**
     * MIG-4: plain numbers print as plain digits on every path, and a plural
     * still selects by the number.
     */
    public function testPlainNumbersPrintAsPlainDigits(): void
    {
        $this->assertSame('© 2026 Northwind', $this->interpolator->interpolate('© {year} Northwind', ['year' => 2026], 'en-us', true));
        $this->assertSame('Total 1234.5', $this->interpolator->interpolate('Total {n}', ['n' => 1234.5], 'de-de', true));
        $this->assertSame('1 item', $this->interpolator->interpolate('{count, plural, one {# item} other {# items}}', ['count' => 1], 'en-us', true));
        $this->assertSame('1234 items', $this->interpolator->interpolate('{count, plural, one {# item} other {# items}}', ['count' => 1234], 'en-us', true));
        $this->assertSame('1234 items in 2026', $this->interpolator->interpolate('{count, plural, one {# item} other {{count} items}} in {year}', ['count' => 1234, 'year' => 2026], 'fr-fr', true));
        $this->assertSame('12345 pts', $this->interpolator->interpolate('{n, number} pts', ['n' => 12345], 'en-us', true));
        $this->assertSame('1233 others', $this->interpolator->interpolate('{n, plural, offset:1 =1 {just you} other {# others}}', ['n' => 1234], 'en-us', true));
    }

    public function testPlainNumbersKeepARecoveredSentenceAndHashInASelectAsText(): void
    {
        $this->assertSame('They paid 12345', $this->interpolator->interpolate('{g, select, male {He} other {They}} paid {n}', ['n' => 12345], 'en-us', true));
        $this->assertSame('# 1234', $this->interpolator->interpolate('{n, plural, other {{g, select, other {#}} #}}', ['n' => 1234, 'g' => 'x'], 'en-us', true));
    }

    public function testWithoutPlainNumbersTheSameCallsAreGroupedForTheLocale(): void
    {
        $this->assertSame('© 2,026 Northwind', $this->interpolator->interpolate('© {year} Northwind', ['year' => 2026], 'en-us'));
        $this->assertSame('1,234 items', $this->interpolator->interpolate('{count, plural, one {# item} other {# items}}', ['count' => 1234], 'en-us'));
        $this->assertSame('12,345 pts', $this->interpolator->interpolate('{n, number} pts', ['n' => 12345], 'en-us'));
    }

}
